import 'package:flutter/material.dart';
class AppHeader extends StatelessWidget implements PreferredSizeWidget{final String title;final IconData? actionIcon;final VoidCallback? onActionTap;final bool showBackButton;const AppHeader({super.key,required this.title,this.actionIcon,this.onActionTap,this.showBackButton=false});@override Widget build(BuildContext context)=>AppBar(elevation:0,scrolledUnderElevation:0,backgroundColor:Theme.of(context).scaffoldBackgroundColor,automaticallyImplyLeading:showBackButton,titleSpacing:showBackButton?0:20,title:Text(title,style:const TextStyle(fontWeight:FontWeight.w900,fontSize:20)),actions:[if(actionIcon!=null)IconButton(icon:Icon(actionIcon),onPressed:onActionTap),const SizedBox(width:6)]);@override Size get preferredSize=>const Size.fromHeight(kToolbarHeight);}
